Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).
Notation zlen l := (Z.of_nat (length l)).

(* [comment removed for export] *)
Definition z1rel (L pt b st : Z) : Prop :=
  (st = 0 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b <= 64 /\ (8 <= pt -> b <= 8))) \/
  (st = 3 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b < 2^31)).

Definition z4s1_s12_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp c2 c3 m13 m14 m15 m16 e15 e16 k6 k8 k9 k16 k24 k31 x12 : word)
         (SPF SS n SBL SBH l1 l2 pt1 pt2 PTR1 PTR2 P1 P2 P3 P4 Q1 Q2 Q3 Q4 DT4 tl C1 : Z),
    PTR1 = SS + 6 + pt1 -> PTR2 = SS + 6 + l1 + pt2 ->
    z4s_src_ctx RNG mm SS n SBL SBH -> n < 2^26 ->
    rw_cells asegs mm (SPF + 248) [C8 (Z_to_bv 64 (SS + 6 + 8)); C8 (Z_to_bv 64 (SS + 6 + l1 + 8))] ->
    rw_cells asegs mm (SPF + 304) [C8 (Z_to_bv 64 C1)] ->
    rng RNG SPF 576 -> 0x10007fff8000 <= SPF -> SPF + 576 <= 2^47 -> KXGoM.apart SS n SPF 576 ->
    1 <= l1 -> 1 <= l2 -> 6 + l1 + l2 <= n ->
    0 <= pt1 -> (pt1 = 0 \/ pt1 + 8 <= l1) -> 0 <= pt2 -> (pt2 = 0 \/ pt2 + 8 <= l2) ->
    0 <= P1 <= 100 -> 0 <= P2 <= 100 -> (8 <= pt1 -> P1 <= 44) -> (8 <= pt2 -> P2 <= 44) ->
    0 <= bv_unsigned m13 <= 12 -> 0 <= bv_unsigned m14 <= 12 -> 0 <= C1 < 2^64 ->
    (forall (mm' : amem) (PT1 PT2 ST1 ST2 : Z) (b1w b2w c1' c2' j6 j9 j16 j20 j23 j24 : word),
       munch [(SPF + 304, SPF + 312)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       rw_cells asegs mm' (SPF + 304) [C8 c1'] ->
       z1rel l1 (PT1 - (SS + 6)) (bv_unsigned b1w) ST1 -> z1rel l2 (PT2 - (SS + 6 + l1)) (bv_unsigned b2w) ST2 ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 P2) (Z_to_bv 64 SPF) gp tp m16 j6 m15 c2' j9 (Z_to_bv 64 Q1) e16 x12
                                 (Z_to_bv 64 Q3) (Z_to_bv 64 Q4) (Z_to_bv 64 Q2) j16 (Z_to_bv 64 ST1) (Z_to_bv 64 P3) b2w j20
                                 e15 (Z_to_bv 64 PT2) j23 j24 (Z_to_bv 64 ST2) (Z_to_bv 64 PT1) (Z_to_bv 64 2147450880)
                                 (Z_to_bv 64 (64 - tl)) c3 (Z_to_bv 64 P4) b1w)
                            F (Z_to_bv 64 0x8922c) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR (Z_to_bv 64 P2) (Z_to_bv 64 SPF) gp tp m16 k6 m15 k8 k9 (Z_to_bv 64 Q1) e16 x12 (Z_to_bv 64 Q3)
                             (Z_to_bv 64 Q4) (Z_to_bv 64 Q2) k16 (Z_to_bv 64 P1) (Z_to_bv 64 P3) c3 (Z_to_bv 64 DT4) e15
                             (Z_to_bv 64 PTR2) m14 k24 m13 (Z_to_bv 64 PTR1)
                             (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) c2 (Z_to_bv 64 P4) k31)
                        F (Z_to_bv 64 0x890ec) fc None mm (seg_rom asegs)).

Ltac z4s12_post K F304 SPF mm :=
  kx_post_regs_keep;
  let MU := fresh "MU" in let WM := fresh "WM" in
  pose proof (munch_refl [(SPF + 304, SPF + 312)] mm) as MU;
  pose proof (wmono_refl asegs mm) as WM;
  kx_munch_wins MU [(SPF + 304, 8)];
  kx_cellw F304;
  kx_post_mem_free;
  lazymatch goal with |- context [mem_denot ?E mm ?l] => let EM := fresh "EM" in remember (mem_denot E mm l) as mm' eqn:EM; clear EM end;
  kxg_hyp F304;
  kxg_vals;
  kxg_clear;
  eapply K; [ exact MU | exact WM | eassumption | exact F304 | .. ].

Ltac z4s12_rel := unfold z1rel; rewrite ?Z_to_bv_unsigned, ?bv_wrap_small by (unfold bv_modulus; cbn; lia);
  first [ left; split; [reflexivity| lia] | right; split; [reflexivity| lia] ].

